import { Joi, parseCredentials, validatePayload } from "@jibo/server";
import ClientController from "../controllers/client.ctrl";

class ClientHandler {
  public mapping: any;
  private clientCtrl: ClientController;
  constructor(config, registry, sender) {
    this.clientCtrl = new ClientController(config, registry, sender);
    this.mapping = {
      create: { method: this.Create },
      listClients: { method: this.ListClients },
      remove: { method: this.Remove },
      update: { method: this.Update },
    };
  }

  @parseCredentials({ adminOnly: true })
  @validatePayload({
    aco: Joi.object(),
    clientId: Joi.string().required(),
    pkce: Joi.boolean(),
    redirectUri: Joi.string().required(),
    refresh: Joi.boolean(),
    secret: Joi.string(),
    updatedBy: Joi.string().required(),
  })
  public async Create(request) {
    return await this.clientCtrl.create({
      aco: request.payload.aco,
      clientId: request.payload.clientId,
      pkce: request.payload.pkce,
      redirectUri: request.payload.redirectUri,
      refresh: request.payload.refresh,
      secret: request.payload.secret,
      updatedBy: request.payload.updatedBy,
    });
  }

  @parseCredentials({ adminOnly: true })
  @validatePayload({
    aco: Joi.object(),
    id: Joi.string().required(),
    pkce: Joi.boolean(),
    redirectUri: Joi.string(),
    refresh: Joi.boolean(),
    secret: Joi.string(),
    updatedBy: Joi.string().required(),
  })
  public async Update(request) {
    return await this.clientCtrl.update(request.payload.id, {
      aco: request.payload.aco,
      pkce: request.payload.pkce,
      redirectUri: request.payload.redirectUri,
      refresh: request.payload.refresh,
      secret: request.payload.secret,
      updatedBy: request.payload.updatedBy,
    });
  }

  @parseCredentials({ adminOnly: true })
  @validatePayload({
    id: Joi.string().required(),
  })
  public async Remove(request) {
    return await this.clientCtrl.remove(request.payload.id);
  }

  @parseCredentials({ adminOnly: true })
  public async ListClients() {
    return await this.clientCtrl.listClients();
  }

}

export default ClientHandler;

import { Boom, EventSender, log } from "@jibo/server";
import * as Errors from "../errors/client";
import Client from "../schemes/client";

class RomController {
  private eventSender: EventSender;
  constructor(config, registry, sender) {
    this.eventSender = sender;
  }

  /**
   * Creates new client
   *
   * @param clientModel Object that contains client data
   * @returns {Promise} Promise that resolves to created client record
   */
  public async create(clientModel) {
    const existing = await Client.findOne({ clientId: clientModel.clientId });
    if (existing) {
      throw Boom.createWithCode(Errors.CLIENT_ALREADY_EXISTS);
    }
    if (clientModel.aco && !clientModel.aco.sourceId) {
      clientModel.aco.sourceId = clientModel.clientId;
    }
    const client = await Client.create(clientModel);
    return client;
  }

  /**
   * Updates client
   *
   * @param id Client record identifier
   * @param clientModel Object that contains client data
   * @returns {Promise} Promise that resolves to updated client record
   */
  public async update(id, clientModel) {
    const client = await Client.findById(id);
    if (!client) {
      throw Boom.createWithCode(Errors.CLIENT_NOT_FOUND);
    }
    for (const prop of Object.keys(clientModel)) {
      if (clientModel[prop] !== undefined) {
        client[prop] = clientModel[prop];
      }
    }
    if (client.aco && !client.aco.sourceId) {
      client.aco.sourceId = client.clientId;
    }
    await client.save();
    return client;
  }

  /**
   * Removes client
   *
   * @param id Client record identifier
   * @returns {Promise} Promise that resolves to removed client record
   */
  public async remove(id) {
    const result = await Client.findByIdAndRemove(id);
    return result;
  }

  /**
   * Lists clients
   *
   * @returns {Promise} Promise that resolves to list of clients
   */
  public async listClients() {
    return await Client.find();
  }

}

export default RomController;

