import { AWS, log } from "@jibo/server";

export default class StsController {
  private sts: AWS.STS;
  private robotRole: string;
  private bucketName: string;
  private region: string;

  constructor(robotRole: string, bucketName: string, region: string) {
    this.sts = new AWS.STS();
    this.robotRole = robotRole;
    this.bucketName = bucketName;
    this.region = region;
  }

  public async newCredentials(accountId: string, friendlyId: string) {
    const assumed = await this.sts.assumeRole({
      ExternalId: `${friendlyId}_${accountId}`,
      RoleArn: this.robotRole,
      RoleSessionName: `${friendlyId}_${accountId}`,
    }).promise();
    log.debug(`Generated STS credentials: ${assumed.AssumedRoleUser.Arn}. Expires:${assumed.Credentials.Expiration}`);
    const date = new Date();
    const day = `year=${date.getFullYear()}/month=${date.getMonth()}/day=${date.getDate()}`;
    const bucketPath = `lps/robot=${friendlyId}/account=${accountId}/${day}/session=${date.getTime()}/`;

    return {
      bucketName: this.bucketName,
      bucketPath,
      credentials: {
        AccessKeyId: assumed.Credentials.AccessKeyId,
        Expiration: assumed.Credentials.Expiration,
        SecretAccessKey: assumed.Credentials.SecretAccessKey,
        SessionToken: assumed.Credentials.SessionToken,
      },
      region: this.region,
    };
  }
}

