import Boom from "./boom";
import * as Errors from "./errors";

/**
 * Credentials parsing decorator for API methods
 * @returns {Function} Function descriptor to use as decorator
 */

export default function genericValidate({adminOnly = false, matchEmail = null}) {
   return (target, key, descriptor) => {
     const originalMethod = descriptor.value;
     descriptor.value = async function(request) {
      let credentials;
      try {
        credentials = JSON.parse(request.headers["x-amz-credentials"]);
      } catch (e) {
        credentials = {};
      }
      request.auth = request.auth || {};
      request.auth.credentials = credentials;
      if (adminOnly) {
        if (!request.auth.credentials || !request.auth.credentials.isAdmin) {
          throw Boom.createWithCode(Errors.AUTHORIZED_UNDER_ADMIN);
        }
      }
      if (matchEmail) {
        if (!request.auth.credentials && request.auth.credentials.email !== matchEmail) {
          throw Boom.createWithCode(Errors.AUTHORIZED_UNDER_DIFFERENT);
        }
      }
      return await originalMethod.bind(this)(request);
    };
     return descriptor;
  };
}

