import Joi = require("joi");
import Boom from "./boom";
import log from "./log";

export function payload(validationObj) {
  return genericValidate("payload", validationObj);
}
export function headers(validationObj) {
  return genericValidate("headers", validationObj);
}
export function params(validationObj) {
  return genericValidate("params", validationObj);
}
export function query(validationObj) {
  return genericValidate("query", validationObj);
}

function genericValidate(requestPropertyToValidate, validationObj) {
  return (target, key, descriptor) => {
    const originalMethod = descriptor.value;
    descriptor.value = function(request) {
      return new Promise((resolve, reject) => {
        Joi.validate(request[requestPropertyToValidate], validationObj || {}, { allowUnknown: true }, (err) => {
          if (err) {
            log.debug("Validation failed for %s.", key, err.stack);
            reject(Boom.badData(err));
          } else {
            log.debug("Validation ok for:", key);
            originalMethod.bind(this)(request)
              .then((result) => resolve(result))
              .catch((originalErr) => reject(originalErr));
          }
        });
      });
    };
    return descriptor;
  };
}

